return ['domain'=>'publishpress-authors','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'es-ES','project-id-version'=>'PublishPress Authors 4.20.0','pot-creation-date'=>'2026-11-12T07:29:08+00:00','po-revision-date'=>'2026-11-12 08:47+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Authors'=>'PublishPress Authors','https://wordpress.org/plugins/publishpress-authors/'=>'https://wordpress.org/plugins/publishpress-authors/','PublishPress Authors allows you to add multiple authors and guest authors to WordPress posts'=>'PublishPress Authors permite añadir múltiples autores y autores invitados a las entradas de WordPress','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Upgrade to Pro'=>'Actualizar a Pro','This plugin can be deleted.'=>'Este plugin se puede eliminar.','Actions provided by PublishPress plugins.'=>'Acciones proporcionadas por los plugins de PublishPress.','List Authors'=>'Lista de Autores','Lists PublishPress Authors. Results never include author email addresses.'=>'Enumera los Autores de PublishPress. Los resultados nunca incluyen direcciones de correo electrónico de autores.','Get Author'=>'Obtener Autor','Gets one PublishPress Author by term ID. The response never includes an email address.'=>'Obtiene un Autor de PublishPress por ID de término. La respuesta nunca incluye una dirección de correo electrónico.','Get Post Authors'=>'Obtener Autores de la Entrada','Gets the ordered PublishPress Authors assigned to one editable post. The response never includes author email addresses.'=>'Obtiene los Autores de PublishPress ordenados asignados a una entrada editable. La respuesta nunca incluye direcciones de correo electrónico de autores.','Get Author Fields'=>'Obtener Campos de Autor','Lists enabled author-profile field definitions without exposing profile values.'=>'Enumera las definiciones de campos de perfil de autor habilitados sin exponer los valores de perfil.','Author not found.'=>'Autor no encontrado.','Post not found.'=>'Entrada no encontrada.','Authors List'=>'Lista de Autores','Display authors list.'=>'Mostrar lista de autores.','Title'=>'Título','Layout'=>'Diseño','Display All Authors (including those who have not written any posts)'=>'Mostrar Todos los Autores (incluyendo aquellos que no han escrito ninguna entrada)','Enable author\'s search box'=>'Habilitar el cuadro de búsqueda del autor','Limits per page'=>'Límites por página','Authors'=>'Autores','Order'=>'Orden','Order by'=>'Ordenar por','Grid Columns'=>'Columnas de la cuadrícula','Author\'s search box field (Seperate multiple fields by comma(\',\'))'=>'Campo del cuadro de búsqueda del autor (Separar múltiples campos por comas (\',\')','All Authors'=>'Todos los Autores','Guest Authors'=>'Autores Invitados','Users Authors'=>'Autores Usuarios','Ascending'=>'Ascendente','Descending'=>'Descendente','Name'=>'Nombre','Post Counts'=>'Conteos de Entradas','First Name'=>'Nombre de Pila','Last Name'=>'Apellido','Showing authors starting with %s'=>'Mostrando autores que comienzan con %s','Showing all authors'=>'Mostrando todos los autores','No authors found.'=>'No se han encontrado autores.','Loading authors...'=>'Cargando autores...','Unable to load authors.'=>'No se pueden cargar los autores.','Default Search'=>'Búsqueda predeterminada','Search Box'=>'Cuadro de búsqueda','Search'=>'Buscar','Search authors'=>'Buscar autores','Search authors by'=>'Buscar autores por','No recent posts from this author'=>'No hay publicaciones recientes de este autor','Request status.'=>'Estado de la solicitud.','Security error. Kindly reload this page and try again'=>'Error de seguridad. Por favor, recargue esta página y vuelva a intentarlo','You cannot edit an author profile linked to an administrator account.'=>'No puedes editar un perfil de autor vinculado a una cuenta de administrador.','You do not have permission to edit this author profile because it is linked to a user account you do not have permission to edit.'=>'No tienes permiso para editar este perfil de autor porque está vinculado a una cuenta de usuario que no tienes permiso para editar.','Sorry, this WordPress user is already mapped to another Author. By default, each user can only be connected to one Author profile.'=>'Lo sentimos, este usuario de WordPress ya está asignado a otro autor. De forma predeterminada, cada usuario solo puede estar conectado a un perfil de autor.','Registered User is required.'=>'Se requiere un usuario registrado.','Author URL cannot be empty.'=>'La URL del autor no puede estar vacía.','Another user with Author URL already exists.'=>'Ya existe otro usuario con la URL del autor.','Author name is required'=>'Se requiere el nombre del autor','No post ID provided for Authors_Iterator constructor. Are you not in a loop or is $post not set?'=>'No se proporcionó un ID de publicación para el constructor Authors_Iterator. ¿No estás en un bucle o $post no está configurado?','Display name publicly as'=>'Mostrar nombre públicamente como','Email'=>'Correo electrónico','Author Type'=>'Tipo de autor','Guest Author With User Account'=>'Autor invitado con cuenta de usuario','Registered Author With User Account'=>'Autor registrado con cuenta de usuario','Guest Author With No User Account'=>'Autor invitado sin cuenta de usuario','Edit User'=>'Editar usuario','Edit Author Profile'=>'Editar perfil de autor','Create Author Profile'=>'Crear perfil de autor','General'=>'General','Avatar'=>'Avatar','Author'=>'Autor','Registered User'=>'Usuario registrado','Biographical Info'=>'Información biográfica','Avatar Source'=>'Fuente del avatar','Default Avatar'=>'Avatar predeterminado','(Uses the %1$s Email field %2$s to find the Gravatar account if default avatar is not uploaded in Authors Settings)'=>'(Utiliza el campo de correo electrónico %1$s %2$s para encontrar la cuenta de Gravatar si no se ha subido un avatar predeterminado en la configuración de autores)','Custom image'=>'Imagen personalizada','Alternative Text'=>'Texto alternativo','Describe the avatar. Leave blank to use the Media Library alternative text or author name.'=>'Describe el avatar. Deja en blanco para usar el texto alternativo de la biblioteca de medios o el nombre del autor.','Decorative Image'=>'Imagen decorativa','Use empty alternative text when this avatar is decorative.'=>'Utiliza texto alternativo vacío cuando este avatar sea decorativo.','Website'=>'Sitio web','Author Category'=>'Categoría de autor','Select the default Category for this Author. This will be used when the Author is added to new posts.'=>'Selecciona la categoría predeterminada para este autor. Esta se usará cuando el autor sea añadido a nuevas publicaciones.','Do not show this profile publicly'=>'No mostrar este perfil públicamente','(required)'=>'(requerido)','Select image'=>'Seleccionar imagen','Remove this image'=>'Eliminar esta imagen','Select a user'=>'Seleccionar un usuario','Author email error'=>'Error de correo electrónico del autor','Create an author profile for a current user account. You can select users who are allowed to edit posts. This user will be able to update their profile.'=>'Crea un perfil de autor para una cuenta de usuario actual. Puedes seleccionar usuarios que están autorizados para editar publicaciones. Este usuario podrá actualizar su perfil.','Create an author profile and a linked user account. This account will be in the "Guest Author" role and will not be able to login to the WordPress dashboard or update their profile.'=>'Crea un perfil de autor y una cuenta de usuario vinculada. Esta cuenta estará en el rol de "Autor invitado" y no podrá iniciar sesión en el dashboard de WordPress ni actualizar su perfil.','Create an author profile with no linked user account. This option is lightweight but may have compatibility issues with other themes and plugins.'=>'Crea un perfil de autor sin cuenta de usuario vinculada. Esta opción es ligera pero puede tener problemas de compatibilidad con otros temas y plugins.','Author Email'=>'Correo electrónico del autor','User Account'=>'Cuenta de usuario','Sync author and user fields'=>'Sincronizar campos de autor y usuario','Convert to Guest Author With User Account'=>'Convertir a autor invitado con cuenta de usuario','Update post count'=>'Actualizar conteo de publicaciones','No authors were updated'=>'No se actualizaron autores','Updated %d authors'=>'Se actualizaron %d autores','An author with the name provided already exists.'=>'Ya existe un autor con el nombre proporcionado.','An author email is required when creating new User Author.'=>'Se requiere un correo electrónico de autor al crear un nuevo autor de usuario.','This email address is already linked to another WordPress user.'=>'Esta dirección de correo electrónico ya está vinculada a otro usuario de WordPress.','Now inspecting or updating %d total authors'=>'Ahora inspeccionando o actualizando %d autores en total','%1$d/%2$d: Inspecting the user %3$d'=>'%1$d/%2$d: Inspeccionando al usuario %3$d','All is set. No author need to be updated'=>'Todo está configurado. No es necesario actualizar autores','Now inspecting or updating %d total posts'=>'Ahora inspeccionando o actualizando %d publicaciones en total','%1$d/%2$d: Inspecting the post %3$d'=>'%1$d/%2$d: Inspeccionando la publicación %3$d','Creating author term for the user %d'=>'Creando término de autor para el usuario %d','Adding the author term %1$d to the post %2$d'=>'Añadiendo el término de autor %1$d a la publicación %2$d','All is set. No posts need to be updated'=>'Todo está configurado. No es necesario actualizar publicaciones','Configure'=>'Configurar','Please correct your form errors below and try again.'=>'Por favor corrige los errores de tu formulario a continuación y vuelve a intentarlo.','Cheatin&#8217; uh?'=>'¿Haciendo trampa?','You do not have necessary permissions to complete this action.'=>'No tienes los permisos necesarios para completar esta acción.','Post does not exist'=>'La publicación no existe','No author term'=>'Sin término de autor','"post_author" is empty'=>'"post_author" está vacío','Drag-and-drop Authors to add them to the %s category'=>'Arrastra y suelta autores para añadirlos a la categoría %s','Search for an author'=>'Buscar un autor','This option is showing because you do not have a WordPress user selected as an author. For some tasks, it can be helpful to have a user selected here. This user will not be visible on the front of your site.'=>'Esta opción se muestra porque no tienes un usuario de WordPress seleccionado como autor. Para algunas tareas, puede ser útil tener un usuario seleccionado aquí. Este usuario no será visible en la parte frontal de tu sitio.','Search for an user'=>'Buscar un usuario','Author Box'=>'Caja de Autor','Default Author Box'=>'Caja de Autor Predeterminada','Hide Author Box'=>'Ocultar Caja de Autor','Filter posts by author'=>'Filtrar publicaciones por autor','Remove %s'=>'Eliminar %s','New author added.'=>'Nuevo autor añadido.','Author profile deleted.'=>'Perfil de autor eliminado.','Author profile updated.'=>'Perfil de autor actualizado.','Error adding author account.'=>'Error al añadir la cuenta de autor.','Error updating author profile.'=>'Error al actualizar el perfil del autor.','Authors deleted.'=>'Autores eliminados.','Author URL'=>'URL del autor','Co-Authors Plus must be installed and active.'=>'Co-Authors Plus debe estar instalado y activo.','Read more.'=>'Leer más.','The results could not be loaded.'=>'No se pudieron cargar los resultados.','Please delete %d character'=>'Por favor, elimina %d carácter','Please delete %d characters'=>'Por favor, elimina %d caracteres','Please enter %d or more character'=>'Por favor, introduce %d o más carácter','Please enter %d or more characters'=>'Por favor, introduce %d o más caracteres','Loading more results...'=>'Cargando más resultados...','You can only select %d item'=>'Solo puedes seleccionar %d elemento','You can only select %d items'=>'Solo puedes seleccionar %d elementos','No results found'=>'No se encontraron resultados','Searching...'=>'Buscando...','Remove all items'=>'Eliminar todos los elementos','No results match'=>'No hay resultados que coincidan','Need PublishPress Authors Support?'=>'¿Necesitas soporte de PublishPress Authors?','If you need help or have a new feature request, let us know.'=>'Si necesitas ayuda o tienes una solicitud de nueva función, háznoslo saber.','Request Support'=>'Solicitar Soporte','Detailed documentation is also available on the plugin website.'=>'Documentación detallada también está disponible en el sitio web del plugin.','View Knowledge Base'=>'Ver Base de Conocimientos','Text'=>'Texto','Multiline text'=>'Texto multilínea','WYSIWYG Editor'=>'Editor WYSIWYG','Link'=>'Enlace','Email address'=>'Dirección de correo electrónico','Active'=>'Activo','Disabled'=>'Desactivado','Optional'=>'Opcional','Required'=>'Requerido','No'=>'No','Yes, this is a Social Profile'=>'Sí, este es un Perfil Social','Select an option'=>'Selecciona una opción','dofollow'=>'dofollow','nofollow'=>'nofollow','Discover authors, categories and boxes for a post byline'=>'Descubre autores, categorías y cajas para una línea de post','Read paginated existing author term IDs and enabled author categories plus native Author Box choices for one editable post. Uses byline permissions rather than granting profile management. Never creates profiles for unassigned WordPress users. Follow each list total_pages separately.'=>'Lee los IDs de términos de autores existentes paginados y las categorías de autores habilitadas más las opciones nativas de Author Box para un post editable. Usa permisos de línea de post en lugar de otorgar gestión de perfil. Nunca crea perfiles para usuarios de WordPress no asignados. Sigue cada lista total_pages por separado.','Read post authors and Author Box'=>'Lee autores de post y Author Box','Read exact ordered author term IDs, author-category assignments, fallback WordPress author and per-post Author Box with a revision hash. Requires native byline and edit_post permissions; never guesses author IDs or writes during reads.'=>'Lee IDs de términos de autores ordenados exactos, asignaciones de autor-categoría, autor de WordPress por defecto y Author Box por post con un hash de revisión. Requiere permisos nativos de línea de post y edit_post; nunca adivina IDs de autores ni escribe durante lecturas.','Update post authors and Author Box'=>'Actualiza autores de post y Author Box','Replace a post byline with ordered author_ids, or patch category assignments and its Author Box. Omitted fields are preserved. Requires the latest hash and an enabled post type. dry_run previews without saving. Discover authors, categories and native layout choices first.'=>'Reemplaza una línea de post con ordered author_ids, o parchea asignaciones de categoría y su Author Box. Los campos omitidos se preservan. Requiere el último hash y un tipo de post habilitado. dry_run prevé sin guardar. Descubre autores, categorías y opciones de diseño nativas primero.','Update bylines on multiple posts'=>'Actualiza líneas de post en múltiples posts','Apply explicit per-post byline changes after validating every object, revision hash and author/category identifier. Each change has its own post_id and expected_hash. dry_run previews all targets without saving. On failure, prior writes are compensated with their original bylines.'=>'Aplica cambios explícitos de línea de post por post después de validar cada objeto, hash de revisión e identificador de autor/categoría. Cada cambio tiene su propio post_id y expected_hash. dry_run prevé todos los objetivos sin guardar. En caso de fallo, las escrituras anteriores se compensan con sus líneas originales.','Choose a post type enabled for Authors.'=>'Elige un tipo de post habilitado para Autores.','The post byline changed. Read it again before saving.'=>'La línea de post ha cambiado. Léelo de nuevo antes de guardar.','Choose existing author term IDs.'=>'Elige IDs de términos de autores existentes.','Empty bylines must first be enabled in Authors settings.'=>'Las líneas de post vacías deben habilitarse primero en la configuración de Autores.','Category assignments must refer to the selected authors.'=>'Las asignaciones de categoría deben referirse a los autores seleccionados.','Multiple author categories are disabled.'=>'Múltiples categorías de autores están desactivadas.','Choose an enabled author category available for this post type.'=>'Elige una categoría de autor habilitada disponible para este tipo de post.','An empty byline preserves its existing fallback WordPress author.'=>'Una línea de post vacía preserva su autor de WordPress por defecto existente.','Choose an existing fallback WordPress user.'=>'Elige un usuario de WordPress por defecto existente.','Choose an available Author Box and enable per-post box selection.'=>'Elige un Author Box disponible y habilita la selección de caja por post.','The byline save failed and its original state could not be restored. Read the post before retrying.'=>'El guardado de la línea de post falló y su estado original no pudo ser restaurado. Lee el post antes de volver a intentar.','Could not save the complete post byline.'=>'No se pudo guardar la línea de post completa.','Include each post only once in a batch.'=>'Incluye cada post solo una vez en un lote.','The batch failed and some original bylines could not be restored. Read all target posts before retrying.'=>'El lote falló y algunas líneas de post originales no pudieron ser restauradas. Lee todos los posts de destino antes de volver a intentar.','List Author Categories'=>'Lista de Categorías de Autores','Read native author category IDs, singular/plural names, order, enabled state and schema settings. These group a post byline and differ from post categories. Pro adds per-post-type targeting. Results are paginated.'=>'Lee IDs de categoría de autor nativos, nombres singulares/plurales, orden, estado habilitado y configuraciones de esquema. Estos agrupan una línea de post y difieren de las categorías de post. Pro añade segmentación por tipo de post. Los resultados están paginados.','Discover Author Category fields'=>'Descubre campos de Categoría de Autor','Read category identifiers, label and grouping settings, and active-edition targeting choices. Categories describe author byline roles such as Writer or Reviewer, not WordPress post categories.'=>'Lee identificadores de categoría, etiqueta y configuraciones de agrupación, y opciones de segmentación de edición activa. Las categorías describen roles de línea de autor como Escritor o Revisor, no categorías de post de WordPress.','Read Author Category'=>'Lee Categoría de Autor','Read one verified native author category and revision hash. Use this hash when updating or deleting.'=>'Lee una categoría de autor nativa verificada y hash de revisión. Usa este hash al actualizar o eliminar.','Create or update Author Category'=>'Crea o actualiza Categoría de Autor','Create a category with category_name and plural_name or patch an existing ID using expected_hash. Preserves omitted fields, validates post types and requires Pro for post-type targeting. dry_run previews without saving. Category order is an integer position.'=>'Crea una categoría con category_name y plural_name o parchea un ID existente usando expected_hash. Preserva campos omitidos, valida tipos de post y requiere Pro para segmentación por tipo de post. dry_run prevé sin guardar. El orden de categoría es una posición entera.','Delete unused Author Category'=>'Elimina Categoría de Autor no utilizada','Delete an unused native category and its metadata. Existing post category relationships or author-profile defaults must be reassigned first. Requires expected_hash; dry_run checks without deleting.'=>'Elimina una categoría nativa no utilizada y sus metadatos. Las relaciones de categoría de post existentes o los valores por defecto de perfil de autor deben ser reasignados primero. Requiere expected_hash; dry_run verifica sin eliminar.','Singular name'=>'Nombre singular','Plural name'=>'Nombre plural','Schema property'=>'Propiedad del esquema','Author Category not found.'=>'Categoría de autor no encontrada.','The category changed. Read it again before saving.'=>'La categoría ha cambiado. Léela de nuevo antes de guardar.','Use exact category field types from discovery.'=>'Utiliza los tipos de campo de categoría exactos de la búsqueda.','Singular and plural category names are required.'=>'Se requieren nombres de categoría singular y plural.','Category post-type targeting requires Authors Pro.'=>'El direccionamiento de tipo de publicación de categoría requiere Authors Pro.','Choose registered post types.'=>'Elige tipos de publicaciones registrados.','An Author Category with this slug already exists.'=>'Ya existe una Categoría de Autor con este slug.','Could not save the native Author Category.'=>'No se pudo guardar la Categoría de Autor nativa.','The category save failed; the original state was restored.'=>'El guardado de la categoría falló; se restauró el estado original.','The category save failed and restoration was incomplete. Read it before retrying.'=>'El guardado de la categoría falló y la restauración fue incompleta. Léela antes de volver a intentar.','The category changed. Read it again before deleting.'=>'La categoría ha cambiado. Léela de nuevo antes de eliminar.','Reassign category references before deleting.'=>'Reasigna las referencias de categoría antes de eliminar.','The category could not be deleted.'=>'No se pudo eliminar la categoría.','Use the exact native field type shown in discovery.'=>'Utiliza el tipo de campo nativo exacto mostrado en la búsqueda.','Choose a list of values from field discovery.'=>'Elige una lista de valores de la búsqueda de campos.','Field choice lists require string values from discovery.'=>'Las listas de opciones de campo requieren valores de cadena de la búsqueda.','Box shortcodes require parallel lists of shortcode and position strings.'=>'Los shortcodes de caja requieren listas paralelas de cadenas de shortcode y posición.','Box shortcodes require string values.'=>'Los shortcodes de caja requieren valores de cadena.','Each box shortcode needs one matching position.'=>'Cada shortcode de caja necesita una posición coincidente.','The native field sanitizer is unavailable.'=>'El saneador de campo nativo no está disponible.','List saved Author Lists'=>'Listar listas de autores guardadas','Read a bounded page of saved Author List presets. Each preset has its own ID and shortcode. This is configuration, not a list of author profiles. Includes native active/trash status.'=>'Leer una página limitada de presets de lista de autores guardadas. Cada preset tiene su propio ID y shortcode. Esta es la configuración, no una lista de perfiles de autor. Incluye estado nativo activo/papelera.','Read saved Author List'=>'Leer lista de autores guardada','Read one verified list preset, its shortcode and revision hash. Editing a list does not change author profiles, post bylines or Author Boxes.'=>'Leer un preset de lista verificado, su shortcode y hash de revisión. Editar una lista no cambia los perfiles de autor, líneas de publicación ni Cajas de Autor.','Discover Author List fields'=>'Descubrir campos de lista de autores','Read native layout, display-field, grouping, image, filter and active-edition search/pagination choices. Pro-only controls appear only with Pro active; promotional controls are excluded.'=>'Leer opciones de diseño nativo, campo de visualización, agrupación, imagen, filtro y búsqueda/paginación de edición activa. Los controles solo para Pro aparecen solo con Pro activo; los controles promocionales están excluidos.','Create or update Author List'=>'Crear o actualizar lista de autores','Create a list with native title and layout fields, or patch a verified preset using its latest hash. Generates a native publishpress_authors_list shortcode from validated fields. Preserves omitted fields and other lists. Use status active to restore a trashed preset. dry_run previews without saving.'=>'Crear una lista con campos de título y diseño nativos, o parchear un preset verificado utilizando su último hash. Genera un shortcode nativo publishpress_authors_list a partir de campos validados. Preserva campos omitidos y otras listas. Usa el estado activo para restaurar un preset eliminado. dry_run previsualiza sin guardar.','Trash or delete Author List'=>'Enviar a la papelera o eliminar lista de autores','Trash a verified saved list, or explicitly use permanent true to remove its preset. Requires the latest hash. Does not delete posts or author profiles. dry_run checks without saving.'=>'Enviar a la papelera una lista guardada verificada, o usar explícitamente permanente true para eliminar su preset. Requiere el último hash. No elimina publicaciones ni perfiles de autor. dry_run verifica sin guardar.','Author List not found.'=>'Lista de autores no encontrada.','The Author List changed. Read it again before saving.'=>'La lista de autores ha cambiado. Léela de nuevo antes de guardar.','An Author List requires a title and native layout.'=>'Una lista de autores requiere un título y un diseño nativo.','The Author List changed. Read it again before deleting.'=>'La lista de autores ha cambiado. Léela de nuevo antes de eliminar.','List Author Boxes'=>'Listar Cajas de Autor','Read Author Box'=>'Leer Caja de Autor','Discover Author Box fields'=>'Descubrir campos de Caja de Autor','Save Author Box'=>'Guardar caja de autor','Trash Author Box'=>'Papelera de caja de autor','List author field definitions'=>'Listar definiciones de campo de autor','Read author field definition'=>'Leer definición de campo de autor','Discover custom field options'=>'Descubrir opciones de campo personalizado','Save author field definition'=>'Guardar definición de campo de autor','Trash author field definition'=>'Papelera de definición de campo de autor','New boxes only: choose a native Free or Pro template from field discovery.'=>'Solo nuevas cajas: elige una plantilla nativa Free o Pro de descubrimiento de campos.','List a bounded page of native objects with IDs, titles, slugs and status. Only editable objects are returned. Read the exact object and its field schema before editing. Follow total_pages even if permissions filter a page to empty.'=>'Listar una página limitada de objetos nativos con IDs, títulos, slugs y estado. Solo se devuelven objetos editables. Lee el objeto exacto y su esquema de campo antes de editar. Sigue total_pages incluso si los permisos filtran una página a vacía.','Read a verified native object with its editable settings and revision hash. Does not expose arbitrary post metadata. Custom field definitions are distinct from author profile values.'=>'Leer un objeto nativo verificado con sus configuraciones editables y hash de revisión. No expone metadatos de publicación arbitrarios. Las definiciones de campo personalizado son distintas de los valores del perfil del autor.','Discover native editor labels, field types, supported choices and edition-specific fields. Optional id selects an existing object. Unknown or inactive-edition fields are rejected during saves.'=>'Descubrir etiquetas de editor nativo, tipos de campo, opciones soportadas y campos específicos de edición. El id opcional selecciona un objeto existente. Los campos desconocidos o de edición inactiva son rechazados durante los guardados.','Create a native object or patch a verified ID using discovered typed fields. New objects need a title and default to draft. Updates require expected_hash, preserve omitted fields and use native sanitizers. dry_run validates without saving. menu_order controls native list ordering. Managing custom field definitions requires Pro.'=>'Crear un objeto nativo o parchear un ID verificado utilizando campos tipados descubiertos. Los nuevos objetos necesitan un título y predeterminan a borrador. Las actualizaciones requieren expected_hash, conservar campos omitidos y utilizar desinfectantes nativos. dry_run valida sin guardar. menu_order controla el orden de la lista nativa. Gestionar definiciones de campo personalizado requiere Pro.','Trash a verified native object with delete_post permission and expected_hash. Does not permanently delete it when Trash is disabled. Existing references are not rewritten. dry_run checks without deleting; custom field deletion requires Pro.'=>'Papelera de un objeto nativo verificado con permiso delete_post y expected_hash. No se elimina permanentemente cuando la Papelera está deshabilitada. Las referencias existentes no se reescriben. dry_run verifica sin eliminar; la eliminación de campos personalizados requiere Pro.','Field Type'=>'Tipo de campo','Field Status'=>'Estado del campo','Required or optional'=>'Requerido u opcional','Social Profile'=>'Perfil social','Link relationship'=>'Relación de enlace','Open link in a new tab'=>'Abrir enlace en una nueva pestaña','Show in REST API'=>'Mostrar en REST API','Description'=>'Descripción','Native object not found.'=>'Objeto nativo no encontrado.','This object changed. Read it again before editing.'=>'Este objeto ha cambiado. Léelo de nuevo antes de editar.','A title is required for a new object.'=>'Se requiere un título para un nuevo objeto.','You cannot create or publish this native object.'=>'No puedes crear o publicar este objeto nativo.','This field name is reserved for account identity or security.'=>'Este nombre de campo está reservado para la identidad de cuenta o seguridad.','Choose a unique author field slug.'=>'Elige un slug de campo de autor único.','Choose discovered profile field names for the box order.'=>'Elige nombres de campos de perfil descubiertos para el orden de las cajas.','Choose a discovered template when creating a new Author Box.'=>'Elige una plantilla descubierta al crear una nueva Caja de Autor.','The field order could not be saved. Read the object before retrying.'=>'No se pudo guardar el orden de los campos. Lee el objeto antes de volver a intentar.','Native metadata save failed; the original object was restored.'=>'El guardado de metadatos nativos falló; el objeto original fue restaurado.','Native metadata save failed and the original object could not be fully restored. Read it before retrying.'=>'El guardado de metadatos nativos falló y el objeto original no pudo ser restaurado completamente. Léelo antes de volver a intentar.','This object changed. Read it again before deleting.'=>'Este objeto ha cambiado. Léelo de nuevo antes de eliminar.','You cannot trash this object, or Trash is disabled.'=>'No puedes enviar este objeto a la papelera, o la Papelera está deshabilitada.','The native object could not be trashed.'=>'No se pudo enviar el objeto nativo a la papelera.','Discover author profile fields'=>'Descubrir campos de perfil de autor','Read native field labels, types and choices for an author. Enabled custom fields are included. Email, account identity, passwords and privileged user fields are excluded from profile fields; account linking has a separate action.'=>'Leer etiquetas de campos nativos, tipos y opciones para un autor. Los campos personalizados habilitados están incluidos. Correo electrónico, identidad de cuenta, contraseñas y campos de usuario privilegiado están excluidos de los campos de perfil; el enlace de cuenta tiene una acción separada.','Read author profile details'=>'Leer detalles del perfil de autor','Read an author profile, public native field values and a revision hash. Hidden REST fields, emails and arbitrary metadata are excluded. Use get-profile-fields before editing and the latest hash to update.'=>'Leer un perfil de autor, valores de campo nativo públicos y un hash de revisión. Los campos REST ocultos, correos electrónicos y metadatos arbitrarios están excluidos. Usa get-profile-fields antes de editar y el último hash para actualizar.','Create or update author profile'=>'Crear o actualizar perfil de autor','Create a guest author, create a profile linked to an existing user_id, or patch an existing profile. Guest creation must be enabled. Discover native fields first; update requires expected_hash. Preserves omitted fields and respects linked-user permissions and administrator profile locks. dry_run validates without saving. Does not create WordPress accounts.'=>'Crea un autor invitado, crea un perfil vinculado a un user_id existente, o actualiza un perfil existente. La creación de invitados debe estar habilitada. Descubre primero los campos nativos; la actualización requiere expected_hash. Preserva los campos omitidos y respeta los permisos de usuario vinculado y los bloqueos de perfil de administrador. dry_run valida sin guardar. No crea cuentas de WordPress.','Link or unlink an author user account'=>'Vincular o desvincular una cuenta de usuario autor','Link an existing author to an existing WordPress user, or use user_id 0 to unlink without deleting or changing the account. Requires the latest profile hash, edit_user on linked accounts, native mapping restrictions and administrator profile policy. dry_run previews without saving.'=>'Vincula un autor existente a un usuario de WordPress existente, o usa user_id 0 para desvincular sin eliminar o cambiar la cuenta. Requiere el último hash de perfil, edit_user en cuentas vinculadas, restricciones de mapeo nativo y política de perfil de administrador. dry_run muestra una vista previa sin guardar.','Delete an unassigned author profile'=>'Eliminar un perfil de autor no asignado','Delete a verified, unassigned author profile using native taxonomy permissions. Reassign existing posts first. Never deletes its linked WordPress account. Requires the latest profile hash; dry_run checks without deleting.'=>'Elimina un perfil de autor verificado y no asignado utilizando permisos de taxonomía nativos. Reasigna primero las publicaciones existentes. Nunca elimina su cuenta de WordPress vinculada. Requiere el último hash de perfil; dry_run verifica sin eliminar.','The author changed. Read the profile again before saving.'=>'El autor ha cambiado. Lee el perfil de nuevo antes de guardar.','You cannot edit the linked user account.'=>'No puedes editar la cuenta de usuario vinculada.','Editing other administrator profiles is disabled.'=>'La edición de otros perfiles de administrador está deshabilitada.','Choose an existing user for a new profile; use link-author-user to remap an existing author.'=>'Elige un usuario existente para un nuevo perfil; usa link-author-user para volver a mapear un autor existente.','This user already has an author profile.'=>'Este usuario ya tiene un perfil de autor.','Choose an editable media attachment for the avatar.'=>'Elige un adjunto de medios editable para el avatar.','Guest author creation requires a name and must be enabled in Authors settings.'=>'La creación de autor invitado requiere un nombre y debe estar habilitada en la configuración de Autores.','A linked author uses the WordPress account nicename as its slug.'=>'Un autor vinculado utiliza el nombre de cuenta de WordPress como su slug.','Choose a unique, non-empty author slug.'=>'Elige un slug de autor único y no vacío.','Profile field save failed; the original state was restored.'=>'Falló el guardado del campo de perfil; se restauró el estado original.','Profile field save failed and restoration was incomplete. Read the profile before retrying.'=>'Falló el guardado del campo de perfil y la restauración fue incompleta. Lee el perfil antes de volver a intentar.','The user is already mapped to another author.'=>'El usuario ya está mapeado a otro autor.','You cannot delete this author profile.'=>'No puedes eliminar este perfil de autor.','Reassign posts before deleting this author profile.'=>'Reasigna publicaciones antes de eliminar este perfil de autor.','Could not delete the author profile.'=>'No se pudo eliminar el perfil de autor.','The settings could not be saved. Read them again before retrying.'=>'No se pudieron guardar las configuraciones. Léelas de nuevo antes de volver a intentar.','Read Authors settings'=>'Leer configuraciones de Autores','Read typed General, Display, Author Pages, Guest Authors and Advanced settings, with defaults and native layout/role/post-type choices. Credentials and license keys are excluded. Whole-module switches use list-features and set-feature-enabled.'=>'Leer las configuraciones generales, de visualización, de Páginas de Autor, Autores Invitados y avanzadas, con valores predeterminados y opciones de diseño/rol/tipo de publicación nativos. Las credenciales y las claves de licencia están excluidas. Los interruptores de módulo completo utilizan list-features y set-feature-enabled.','Update Authors settings'=>'Actualizar configuraciones de Autores','Patch only supplied Authors settings; preserves unrelated settings. Use get-plugin-settings for exact fields and native choices. dry_run validates and returns proposed values without saving. Author Pages changes refresh rewrite rules. Pro branding requires Pro.'=>'Parchear solo las configuraciones de Autores suministradas; preserva configuraciones no relacionadas. Usa get-plugin-settings para campos exactos y elecciones nativas. dry_run valida y devuelve valores propuestos sin guardar. Los cambios en Páginas de Autor actualizan las reglas de reescritura. Pro branding requiere Pro.','Discover Authors features and actions'=>'Descubrir características y acciones de Autores','List native Authors screens/modules, enabled state, permissions, edition and read/write workflows. Separate author profiles, post bylines, Author Boxes, Author Lists, Author Categories and Pro Custom Fields. Use field discovery before editing.'=>'Listar pantallas/módulos nativos de Autores, estado habilitado, permisos, edición y flujos de trabajo de lectura/escritura. Perfiles de autor separados, bylines de publicaciones, Cajas de Autor, Listas de Autores, Categorías de Autores y Campos Personalizados Pro. Usa el descubrimiento de campos antes de editar.','Enable or disable an Authors module'=>'Habilitar o deshabilitar un módulo de Autores','Change one discovered optional module switch. Autoloaded/core modules cannot be disabled. Does not change individual feature settings or author fields. dry_run previews without saving; refresh the MCP connection after enabling a module.'=>'Cambiar un interruptor de módulo opcional descubierto. Los módulos cargados automáticamente/nucleares no pueden ser deshabilitados. No cambia la configuración de características individuales ni los campos de autor. dry_run muestra una vista previa sin guardar; actualiza la conexión MCP después de habilitar un módulo.','Show Author Box below content'=>'Mostrar Caja de Autor debajo del contenido','Show Author Box above content'=>'Mostrar Caja de Autor encima del contenido','Force empty author'=>'Forzar autor vacío','Username in search field'=>'Nombre de usuario en el campo de búsqueda','Enable plugin author pages'=>'Habilitar páginas de autor del plugin','Show author pages bio'=>'Mostrar biografía de páginas de autor','Show author post featured image'=>'Mostrar imagen destacada de publicaciones de autor','Link author post featured image'=>'Vincular imagen destacada de publicaciones de autor','Show author post excerpt'=>'Mostrar extracto de publicaciones de autor','Remove single user map restriction'=>'Eliminar restricción de mapa de usuario único','Show author post authors'=>'Mostrar autores de publicaciones de autor','Show author post date'=>'Mostrar fecha de publicación del autor','Show author post comments'=>'Mostrar comentarios del autor en la publicación','Show author post category'=>'Mostrar categoría de la publicación del autor','Show author post tags'=>'Mostrar etiquetas de la publicación del autor','Show author post readmore'=>'Mostrar leer más de la publicación del autor','Hide author pages empty posts message'=>'Ocultar mensaje de publicaciones vacías del autor','Show author page title'=>'Mostrar título de la página del autor','Disable quick edit author box'=>'Desactivar cuadro de edición rápida del autor','Enable font awesome'=>'Activar Font Awesome','Allow guest authors without a user account'=>'Permitir autores invitados sin cuenta de usuario','Author boxes opt out'=>'Optar por no recibir cuadros de autor','Allow author multiple categories'=>'Permitir múltiples categorías para el autor','Allow guest authors with a user account'=>'Permitir autores invitados con cuenta de usuario','Show editor author box selection'=>'Mostrar selección de cuadro de autor del editor','Default avatar decorative'=>'Avatar decorativo predeterminado','Translate author taxonomy'=>'Traducir taxonomía del autor','Allow administrators to edit other administrator profiles'=>'Permitir a los administradores editar perfiles de otros administradores','Show email link in legacy Author Box'=>'Mostrar enlace de correo electrónico en el cuadro de autor legado','Show website link in legacy Author Box'=>'Mostrar enlace del sitio web en el cuadro de autor legado','Legacy Author Box color scheme'=>'Esquema de color del cuadro de autor legado','Choose a native Author Box layout ID or slug from discovery.'=>'Elige un ID o slug de diseño de cuadro de autor nativo de descubrimiento.','List'=>'Lista','Grid'=>'Cuadrícula','Positive pixel size, or an empty string to use the native image size.'=>'Tamaño de píxel positivo, o una cadena vacía para usar el tamaño de imagen nativo.','Pro: display PublishPress branding.'=>'Pro: mostrar la marca de PublishPress.','Roles available when mapping existing WordPress users to authors.'=>'Roles disponibles al mapear usuarios de WordPress existentes a autores.','Automatically create author profiles for new users in these roles.'=>'Crear automáticamente perfiles de autor para nuevos usuarios en estos roles.','Default author taxonomy term ID for new posts; zero uses native defaults.'=>'ID de término de taxonomía de autor predeterminado para nuevas publicaciones; cero usa los valores predeterminados nativos.','Existing WordPress user ID used as the core post author for guest bylines.'=>'ID de usuario de WordPress existente utilizado como el autor principal de la publicación para bylines de invitados.','Native guest account setting. MCP profile actions only link existing accounts and never create user accounts.'=>'Configuración de cuenta de invitado nativa. Las acciones de perfil de MCP solo vinculan cuentas existentes y nunca crean cuentas de usuario.','Posts per author page: -1 shows all posts; zero uses the native default of 10.'=>'Publicaciones por página de autor: -1 muestra todas las publicaciones; cero usa el valor predeterminado nativo de 10.','Use exact setting types from discovery.'=>'Usar tipos de configuración exactos de descubrimiento.','Role lists require role-name strings from discovery.'=>'Las listas de roles requieren cadenas de nombre de rol de descubrimiento.','Post type switches require true or false.'=>'Los interruptores de tipo de publicación requieren verdadero o falso.','This post type is enabled by site code and cannot be disabled here.'=>'Este tipo de publicación está habilitado por el código del sitio y no se puede desactivar aquí.','Choose an existing default author profile.'=>'Elige un perfil de autor predeterminado existente.','Choose an existing fallback user.'=>'Elige un usuario de respaldo existente.','Choose a valid avatar URL.'=>'Elige una URL de avatar válida.','Native settings validation failed.'=>'La validación de configuraciones nativas falló.','Author Boxes'=>'Cajas de Autor','Author Lists'=>'Listas de Autores','Author Categories'=>'Categorías de Autores','Author field definitions'=>'Definiciones de campo de Autor','Settings, Author Pages and integrations'=>'Configuraciones, Páginas de Autores e integraciones','Author profiles'=>'Perfiles de Autores','Ordered post bylines and per-post Author Box'=>'Bylines de publicaciones ordenadas y Cuadro de Autor por publicación','Choose a discovered optional module.'=>'Elige un módulo opcional descubierto.','Edit My Author Profile'=>'Editar Mi Perfil de Autor','This name is used in several default displays and some search engine integrations.'=>'Este nombre se utiliza en varias visualizaciones predeterminadas y algunas integraciones de motores de búsqueda.','This forms part of the URL for the author’s profile page. If you choose a Mapped User, this URL is taken from the user’s account and can not be changed.'=>'Esto forma parte de la URL de la página de perfil del autor. Si eliges un Usuario Mapeado, esta URL se toma de la cuenta del usuario y no se puede cambiar.','Search Authors'=>'Buscar Autores','Popular Authors'=>'Autores Populares','Parent Author'=>'Autor Principal','Parent Author:'=>'Autor Principal:','Edit Author'=>'Editar Autor','View Author'=>'Ver Autor','Update Author'=>'Actualizar Autor','New Author Profile'=>'Nuevo Perfil de Autor','New Author'=>'Nuevo Autor','Separate authors with commas'=>'Separa los autores con comas','Add or remove authors'=>'Añadir o eliminar autores','Choose from the most used Authors'=>'Elige entre los Autores más utilizados','Back to Authors'=>'Volver a Autores','If you like %1$s please leave us a %2$s rating. Thank you!'=>'Si te gusta %1$s por favor déjanos una %2$s valoración. ¡Gracias!','Posts'=>'Publicaciones','Published posts of the following post types: %s'=>'Publicaciones publicadas de los siguientes tipos de publicación: %s','Click on an author to change them. Drag to change their order.'=>'Haz clic en un autor para cambiarlo. Arrastra para cambiar su orden.','No co-author exists for that term'=>'No existe coautor para ese término','Edit'=>'Editar','Add Author'=>'Añadir Autor','Are you sure you want to remove this author?'=>'¿Estás seguro de que quieres eliminar a este autor?','Click to change this author, or drag to change their position'=>'Haz clic para cambiar a este autor, o arrastra para cambiar su posición','Click on an author to change them. Drag to change their order. Click on <strong>Remove</strong> to remove them.'=>'Haz clic en un autor para cambiarlo. Arrastra para cambiar su orden. Haz clic en <strong>Eliminar</strong> para eliminarlo.','Are you sure you want to delete the authors profiles mapped to users? This action can\'t be undone.'=>'¿Estás seguro de que quieres eliminar los perfiles de autores mapeados a usuarios? Esta acción no se puede deshacer.','Are you sure you want to delete the guest authors profiles? This action can\'t be undone.'=>'¿Estás seguro de que quieres eliminar los perfiles de autores invitados? Esta acción no se puede deshacer.','Are you sure you want to create author profiles for the missed post authors?'=>'¿Estás seguro de que quieres crear perfiles de autor para los autores de publicaciones perdidas?','Are you sure you want to update the author column for all the posts?'=>'¿Estás seguro de que quieres actualizar la columna de autor para todas las publicaciones?','Are you sure you want to update the author slug for all the users?'=>'¿Estás seguro de que quieres actualizar el slug de autor para todos los usuarios?','Are you sure you want to create authors for the selected roles?'=>'¿Estás seguro de que quieres crear autores para los roles seleccionados?','Please, wait...'=>'Por favor, espera...','Sorry, the request returned an error.'=>'Lo siento, la solicitud devolvió un error.','View'=>'Ver','is required'=>'es requerido','Please complete the following required fields to save your changes:'=>'Por favor, complete los siguientes campos obligatorios para guardar sus cambios:','Field title is required'=>'El título del campo es requerido','Mine'=>'Mine','Invalid author list.'=>'Lista de autores no válida.','Post Author'=>'Autor del post','Display a list of authors for the current post.'=>'Mostrar una lista de autores para el post actual.','Single Title'=>'Título único','Plural Title'=>'Título plural','No posts without author terms were found'=>'No se encontraron publicaciones sin términos de autor','%d posts were found without author terms'=>'%d publicaciones se encontraron sin términos de autor','%1$sView all posts%2$s by %3$s'=>'%1$sVer todas las publicaciones%2$s de %3$s',' and '=>' y ','Posts by %s'=>'Publicaciones de %s','Posts by %1$s'=>'Publicaciones de %1$s',', and '=>', y ','All In One Seo Pack Integration'=>'Integración de All In One Seo Pack','Add compatibility with the All In One Seo Pack plugin'=>'Agregar compatibilidad con el plugin All In One Seo Pack','Add support for author boxes.'=>'Agregar soporte para cuadros de autor.','Author Category Boxes'=>'Cuadros de categoría de autor','Shortcode'=>'Shortcode','Default author box'=>'Cuadro de autor predeterminado','Author category box'=>'Cuadro de categoría de autor','%s Author Box setting was not saved because it was changed in another browser or tab. The latest saved value was kept; review the layout and try again.'=>'%s La configuración del cuadro de autor no se guardó porque se cambió en otro navegador o pestaña. Se mantuvo el último valor guardado; revise el diseño y vuelva a intentarlo.|%s Las configuraciones de los cuadros de autor no se guardaron porque se cambiaron en otro navegador o pestaña. Se mantuvieron los últimos valores guardados; revise el diseño y vuelva a intentarlo.','New %1s'=>'Nuevo %1s','Add New %1$s'=>'Agregar nuevo %1$s','Edit %1$s'=>'Editar %1$s','New %1$s'=>'Nuevo %1$s','%2$s'=>'%2$s','View %1$s'=>'Ver %1$s','Search %2$s'=>'Buscar %2$s','No %2$s found'=>'No se encontraron %2$s','No %2$s found in Trash'=>'No se encontraron %2$s en la Papelera','%1$s Image'=>'%1$s Imagen','Set %1$s Image'=>'Establecer imagen de %1$s','Remove %1$s Image'=>'Eliminar imagen de %1$s','Use as %1$s Image'=>'Usar como imagen de %1$s','Filter %2$s list'=>'Filtrar lista de %2$s','%2$s list navigation'=>'%2$s navegación de lista','%2$s list'=>'%2$s lista','Author Box updated.'=>'Caja de Autor actualizada.','Author Box added.'=>'Caja de Autor añadida.','Author Box saved.'=>'Caja de Autor guardada.','Author Box submitted.'=>'Caja de Autor enviada.','%1$s %2$s updated.'=>'%1$s %2$s actualizados.' . "\0" . '%1$s %3$s actualizados.','%1$s %2$s not updated, somebody is editing it.'=>'%1$s %2$s no actualizados, alguien los está editando.' . "\0" . '%1$s %3$s no actualizados, alguien los está editando.','%1$s %2$s permanently deleted.'=>'%1$s %2$s eliminados permanentemente.' . "\0" . '%1$s %3$s eliminados permanentemente.','%1$s %2$s moved to the Trash.'=>'%1$s %2$s movidos a la Papelera.' . "\0" . '%1$s %3$s movidos a la Papelera.','%1$s %2$s restored from the Trash.'=>'%1$s %2$s restaurados de la Papelera.' . "\0" . '%1$s %3$s restaurados de la Papelera.','Duplicate'=>'Duplicado','Invalid Author Box.'=>'Caja de Autor no válida.','You are not allowed to duplicate this Author Box.'=>'No tienes permiso para duplicar esta Caja de Autor.','You are not allowed to create Author Boxes.'=>'No tienes permiso para crear Cajas de Autor.','%s (Copy)'=>'%s (Copia)','Could not duplicate the Author Box.'=>'No se pudo duplicar la Caja de Autor.','Author Box duplicated.'=>'Caja de Autor duplicada.','View all posts'=>'Ver todas las entradas','Theme'=>'Tema','Author Box Preview'=>'Vista previa de la Caja de Autor','Author Box Editor'=>'Editor de Caja de Autor','Layout Slug'=>'Slug de diseño','Banner'=>'Banner','Box Title'=>'Título de la caja','Display Name'=>'Nombre para mostrar','View All Posts'=>'Ver todas las entradas','Author Fields'=>'Campos del Autor','Shortcodes'=>'Shortcodes','Author Recent Posts'=>'Entradas recientes del Autor','Box Layout'=>'Diseño de la caja','Custom CSS'=>'CSS personalizado','Export'=>'Exportar','Import'=>'Importar','Generate Theme Template'=>'Generar plantilla de tema','Shortcode documentation.'=>'Documentación de shortcode.','Post preview'=>'Vista previa de la entrada','Select Preview Post'=>'Seleccionar entrada de vista previa','%1$s for %2$s'=>'%1$s para %2$s','(opens in a new tab)'=>'(se abre en una nueva pestaña)','No Recent Posts by this Author'=>'No hay publicaciones recientes de este autor',