Contacto','taxonomy general nameAuthors'=>'Autores','taxonomy singular nameAuthor'=>'Autor','Author Box post type name%2$s'=>'%2$s','singular author box post type name%1$s'=>'%1$s','custom layout post type menu name%2$s'=>'%2$s','Custom Field post type name%2$s'=>'%2$s','singular custom field post type name%1$s'=>'%1$s','custom field post type menu name%2$s'=>'%2$s']];